const {chromium}=require('/Users/dylanc/.npm/_npx/705bc6b22212b352/node_modules/playwright');
const fs=require('fs'),assert=require('assert');
(async()=>{
const browser=await chromium.launch({headless:true});const page=await browser.newPage({viewport:{width:1440,height:1000}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
const settings={match:.822,guess_band:.05,window_s:6,window_gap_s:1,window_floor:.7,duplicate:.95,ask_delay_s:3,ask_blank_s:4,ask_max:3,views_cap:24};
let objects=[{id:'camera',label:"Ana's camera",owner_label:'Ana',sightings:12,last_seen:Date.now()/1000-20,views:Array.from({length:7},(_,i)=>({id:'view'+i,time:Date.now()/1000,source:'taught'}))}];
const live={status:'Listening',settings,window:{active:false},transcript:Array.from({length:8},(_,i)=>({id:String(i),question:'What did I show you? '+i,answer:'You showed me your camera. I last saw it on the desk.'})),evidence:{knowledge:[],statements:[],memory_ids:[123],memories:[{id:123,label:"Ana's camera",object:'camera',view:'view0',text:'camera',source:'Observed object',time:Date.now()/1000-20}]},memory:{shards:['knowledge','seen'],ms:6.2,hits:[["seen: camera, 20 seconds ago",null]]},control:{targets:[],volume:62}};
let source=fs.readFileSync('tools/talk.html','utf8');
await page.route('http://127.0.0.1:8765/**',async route=>{const path=new URL(route.request().url()).pathname;
 if(path==='/')return route.fulfill({contentType:'text/html',body:source});
 if(path==='/mona-sans.woff2')return route.fulfill({contentType:'font/woff2',body:fs.readFileSync('tools/assets/mona-sans-latin.woff2')});
 if(path==='/status')return route.fulfill({json:{phase:'Listening',active:true,view_ready:true,error:''}});
 if(path==='/robot')return route.fulfill({json:live});
 if(path==='/memory')return route.fulfill({json:objects});
 if(path==='/camera'||path==='/thumb')return route.fulfill({contentType:'image/svg+xml',body:'<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360"><rect width="640" height="360" fill="#14232d"/><rect x="170" y="90" width="300" height="190" rx="18" fill="#303b4d"/><circle cx="320" cy="185" r="65" fill="#101820" stroke="#fb4267" stroke-width="8"/><text x="220" y="315" fill="white" font-family="sans-serif" font-size="22">Ana’s camera</text></svg>'});
 if(path==='/settings'){const data=route.request().postDataJSON();Object.assign(settings,data.reset?{match:.822}:{[data.name]:data.value});return route.fulfill({status:202,body:''});}
 if(path==='/remove_view'){const data=route.request().postDataJSON();objects[0].views=objects[0].views.filter(v=>v.id!==data.view);return route.fulfill({status:202,body:''});}
 return route.fulfill({status:202,body:''});
});
const current=source;source=fs.readFileSync('build/ui-refresh/before.html','utf8');await page.goto('http://127.0.0.1:8765');await page.waitForTimeout(700);await page.screenshot({path:'build/ui-refresh/before-desktop.png',fullPage:true});source=current;await page.reload();await page.locator('.evidenceitem').waitFor();await page.evaluate(()=>document.fonts.ready);
await page.screenshot({path:'build/ui-refresh/live-desktop.png',fullPage:true});
assert(await page.locator('.commands').isVisible());assert.equal(await page.getByRole('heading',{name:'Live camera',exact:true}).count(),0);assert.equal(await page.getByRole('heading',{name:'Conversation',exact:true}).count(),0);assert(await page.evaluate(()=>document.fonts.check('14px \"Mona Sans\"')));assert(await page.evaluate(()=>document.documentElement.scrollHeight<=innerHeight+5));
assert(await page.locator('#transcript').evaluate(e=>e.scrollHeight-e.clientHeight-e.scrollTop<2));
const exchange=await page.locator('.exchange').last().elementHandle();await page.locator('#transcript').evaluate(e=>e.scrollTop=0);live.transcript[7].answer+=' New reply.';
await page.waitForTimeout(600);assert(await page.locator('.exchange').last().evaluate((e,old)=>e===old,exchange));assert(await page.locator('#transcript').evaluate(e=>e.scrollHeight-e.clientHeight-e.scrollTop<2));
await page.getByText('Details',{exact:true}).click();const detail=await page.locator('#retrievalDetails').elementHandle();await page.waitForTimeout(600);assert(await page.locator('#retrievalDetails').evaluate((e,old)=>e===old,detail));
await page.getByRole('button',{name:"Ana's camera",exact:true}).click();await page.locator('.objectcard').waitFor();
assert.equal(await page.locator('.savedview').count(),7);assert.equal(await page.locator('.savedview button:visible').count(),0);
await page.screenshot({path:'build/ui-refresh/memory-desktop.png',fullPage:true});
const width=await page.locator('.views').evaluate(e=>e.firstElementChild.offsetWidth/e.clientWidth);assert(width>.25&&width<.34);
await page.getByRole('button',{name:'Next views of'}).click();await page.waitForTimeout(450);assert(await page.locator('.views').evaluate(e=>e.scrollLeft>0));
await page.getByText('Edit memory',{exact:true}).click();page.on('dialog',d=>d.accept());await page.locator('.savedview button').first().click();await page.waitForTimeout(700);assert.equal(await page.locator('.savedview').count(),6);
await page.getByRole('button',{name:'Settings',exact:true}).click();assert.equal(await page.locator('#settingsPanel input:visible').count(),3);
await page.locator('#setting-match').focus();await page.keyboard.press('ArrowRight');await page.locator('#settingsMessage').filter({hasText:'Saved.'}).waitFor();assert.equal(settings.match,.823);
await page.getByText('Advanced',{exact:true}).click();assert.equal(await page.locator('#settingsPanel input:visible').count(),10);
await page.screenshot({path:'build/ui-refresh/settings-desktop.png',fullPage:true});
await page.setViewportSize({width:390,height:844});await page.getByRole('button',{name:'Memory',exact:true}).click();await page.locator('.objectcard').waitFor();
assert(await page.locator('.views').evaluate(e=>Math.abs(e.firstElementChild.offsetWidth-e.clientWidth)<2));
assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.screenshot({path:'build/ui-refresh/memory-mobile.png',fullPage:true});
await page.getByRole('button',{name:'Live',exact:true}).click();assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));assert(await page.evaluate(()=>document.documentElement.scrollHeight<=document.body.getBoundingClientRect().height+5));await page.screenshot({path:'build/ui-refresh/live-mobile.png',fullPage:true});
console.log(await page.evaluate(()=>({viewport:innerHeight,height:document.documentElement.scrollHeight,body:document.body.getBoundingClientRect().height,grid:document.querySelector('.grid').getBoundingClientRect().toJSON(),foot:document.querySelector('footer').getBoundingClientRect().toJSON(),settings:document.querySelector('#settingsPanel').getBoundingClientRect().toJSON(),memory:document.querySelector('#memoryPanel').getBoundingClientRect().toJSON()})));assert.deepEqual(errors,[]);console.log('PASS: desktop/mobile layout, all carousel views and edit, sliders, evidence link, unchanged DOM, scrollbar auto-scroll, no JavaScript errors.');
await browser.close();
})();
